                    />
                    <button
                        onClick={addTodo}
                        style={{
                            "padding": "12px 24px",
                            "background": "#3b82f6",
                            "color": "#ffffff",
                            "border": "none",
                            "borderRadius": "8px",
                            "fontSize": "16px",
                            "fontWeight": "600",
                            "cursor": "pointer"
