                >
                    <button
                        onClick={lambda { filter = "all"; }}
                        style={{
                            "padding": "8px 16px",
                            "background": ("#3b82f6" if filter == "all" else "#ffffff"),
                            "color": ("#ffffff" if filter == "all" else "#3b82f6"),
