                            "padding": "8px 16px",
                            "background": (
                                "#3b82f6" if filter == "active" else "#ffffff"
                            ),
                            "color": ("#ffffff" if filter == "active" else "#3b82f6"),
                            "border": "1px solid #3b82f6",
                            "borderRadius": "6px",
                            "fontSize": "14px",
