# Typed-base shorthand: members ARE instances of T
# `: int` -> IntEnum, `: str` -> StrEnum, `: T` -> mixin (T, Enum)
enum HttpStatus: int { OK = 200, NOT_FOUND = 404 }
enum Tag: str { OPEN = "open", CLOSE = "close" }

with entry {
    print(Color.RED.value);             # "red"
