```jac
"""useRowPager — shared pager/fetch controller behind the RowBrowser.

Owns the files/path/rows/offset/total/expanded state plus the openFile /
toggleRow / prevPage / nextPage actions that the 01 (Data), 02 (RlData) and
03 (CptData) sections used to triplicate. Parameterized by two fetch callables
the section supplies:

  fetch_files(ctx?)          -> list[FileRefView-like]  (ctx optional, see below)
  fetch_rows(path, off, ctx?) -> {"rows": [...], "total": n}

`ctx` is an optional opaque value threaded from loadFiles(ctx) into both
callables, for sections with an extra fetch dimension (RlData's source):
setting state then fetching in the same handler reads the stale value (React
writes are async — same reason `p`/`off` are passed explicitly everywhere), so
the new source must ride along explicitly. Sections without the dimension just
ignore the extra arg.

Loads the file list (and opens the first file) on mount; loadFiles(ctx) re-runs
that reset for source switches, refreshFiles() re-reads the file list only
(counts changed) without disturbing the open file/page.
"""

def:pub useRowPager(fetch_files: any = None, fetch_rows: any = None, page_size: int = 25) -> dict {
    has files: list = [],
        path: str = "",
        rows: list = [],
        offset: int = 0,
        total: int = 0,
        expanded: int = -1;

    # `p`/`off` are passed explicitly — reading the state right after setting it
    # returns the stale value (React state writes are async).
    async def _fetch(p: str, off: int, ctx: any = None) -> None {
        r = await fetch_rows(p, off, ctx);
        rows = list(r["rows"]);
        total = int(r["total"]);
    }

    async def openFile(p: str) -> None {
        path = p;
        offset = 0;
        expanded = -1;
        await _fetch(p, 0);
    }

    def toggleRow(idx: int) -> None {
        expanded = -1 if expanded == idx else idx;
    }

    async def prevPage -> None {
        if offset > 0 {
            noff = max(0, offset - page_size);
            offset = noff;
            expanded = -1;
            await _fetch(path, noff);
        }
    }

    async def nextPage -> None {
        if offset + len(rows) < total {
            noff = offset + page_size;
            offset = noff;
            expanded = -1;
            await _fetch(path, noff);
        }
    }

    async def loadFiles(ctx: any = None) -> None {
        fs = await fetch_files(ctx);
        files = list(fs);
        offset = 0;
        expanded = -1;
        if len(list(fs)) > 0 {
            path = str(fs[0].path);
            await _fetch(str(fs[0].path), 0, ctx);
        } else {
            path = ""; rows = []; total = 0;
        }
    }

    async def refreshFiles -> None {
        fs = await fetch_files();
        files = list(fs);
    }

    async can with entry {
        await loadFiles();
    }

    return {
        "files": files, "path": path, "rows": rows, "offset": offset,
        "total": total, "expanded": expanded,
        "openFile": openFile, "toggleRow": toggleRow,
        "prevPage": prevPage, "nextPage": nextPage,
        "loadFiles": loadFiles, "refreshFiles": refreshFiles
    };
}

```

```jac
"""Chat history sidebar — ports ui/components/sidebar.tsx.

Chats are grouped by day (most-recent first) under TODAY / ISO-date micro-labels;
each row reveals REN / DEL actions on hover. REN swaps the title for an inline
input (Enter/blur commits via onRename, Escape cancels). The footer MEM gauge
shows resident vs total RAM as `{used} / {ram} GB` plus an 8-cell ▮/░ bar."""

import from ..shared.Button { Button }

def _repeat(ch: str, n: int) -> str {
    s = "";
    i = 0;
    while i < n {
        s = s + ch;
        i = i + 1;
    }
    return s;
}

# Group consecutive chats (already sorted newest-first) by their updated_at day.
def _groups(chats: list) -> list[dict] {
    out: list[dict] = [];
    for c in chats {
        day = str(c.updated_at)[:10];
        if len(out) > 0 and out[len(out) - 1]["day"] == day {
            out[len(out) - 1]["chats"].append(c);
        } else {
            out.append({"day": day, "chats": [c]});
        }
    }
    return out;
}

# JsxElement defs compile to props-object components — params must be optional
# and call sites pass one dict (the _cell/_cmpRow idiom in Train/Evals).
def _mem_gauge(used: any = None, total: any = None) -> JsxElement {
    u = float(str(used or 0.0));
    t = float(str(total or 0.0));
    filled = 0;
    if t > 0.0 {
        filled = int(round(u / t * 8.0));
    }
    if filled > 8 { filled = 8; }
    if filled < 0 { filled = 0; }
    return <div className="dashed-rule pt-3 font-mono text-[10px] text-muted-foreground">
        MEM {f"{u:.1f}"} / {str(int(t))} GB{" "}
        <span className="text-foreground/80">{_repeat("▮", filled)}</span>{_repeat("░", 8 - filled)}
    </div>;
}

def:pub Sidebar(
    chats: list,
    activeId: str,
    ramGb: float,
    residentGb: float,
    todayIso: str,
    busy: bool,
    onNew: Callable[([], None)],
    onOpen: Callable[([str], None)],
    onDelete: Callable[([str], None)],
    onRename: Callable[([str, str], None)]
) -> JsxElement {
    has editingId: str = "",
        draft: str = "";

    def startEdit(id: str, title: str) -> None {
        editingId = id;
        draft = title;
    }

    def commitRename -> None {
        if editingId {
            t = draft.strip();
            if t {
                onRename(editingId, t);
            }
        }
        editingId = "";
        draft = "";
    }

    return <aside className="flex w-56 shrink-0 flex-col border-r border-border bg-card p-3">
        <div className="micro-label mb-3">CHATS</div>
        <Button
            variant="outline"
            onClick={lambda e: MouseEvent { if not busy { onNew(); } }}
            disabled={busy}
            className="mb-3"
        >
            + new chat
        </Button>
        <div className="flex-1 overflow-y-auto">
            {if len(chats) == 0 {
                <p key="empty" className="px-2 font-mono text-[10px] text-muted-foreground/70">no chats yet</p>
                skip;
            }}
            {for grp in _groups(chats) {
                <div key={str(grp["day"])}>
                    <div className="micro-label mb-1 mt-2">{"TODAY" if grp["day"] == todayIso else str(grp["day"])}</div>
                    <div className="space-y-0.5">
                        {for c in list(grp["chats"]) {
                            <div
                                key={str(c.id)}
                                onClick={lambda e: MouseEvent { if not busy { onOpen(str(c.id)); } }}
                                className={"group flex cursor-pointer items-center justify-between rounded-md px-2 py-1.5 text-xs " + (
                                    "bg-accent text-foreground" if str(c.id) == activeId
                                    else "text-muted-foreground hover:bg-muted"
                                ) + (" opacity-50" if busy else "")}
                            >
                                {if editingId == str(c.id) {
                                    <input
                                        key="edit"
                                        autoFocus={True}
                                        value={draft}
                                        onClick={lambda e: MouseEvent { e.stopPropagation(); }}
                                        onChange={lambda e: ChangeEvent { draft = str(e.target.value); }}
                                        onKeyDown={lambda e: KeyboardEvent {
                                            if e.key == "Enter" {
                                                commitRename();
                                            } elif e.key == "Escape" {
                                                editingId = "";
                                                draft = "";
                                            }
                                        }}
                                        onBlur={lambda e: FocusEvent { commitRename(); }}
                                        className="w-full rounded border border-input bg-popover px-1 py-0.5 text-xs text-foreground outline-none"
                                    />
                                    skip;
                                }}
                                {if editingId != str(c.id) {
                                    <span key="title" className="truncate" title={str(c.title)}>{c.title if c.title else "untitled"}</span>
                                    skip;
                                }}
                                {if editingId != str(c.id) {
                                    <div key="acts" className="hidden shrink-0 group-hover:flex">
                                        <Button
                                            variant="ghost"
                                            onClick={lambda e: MouseEvent { e.stopPropagation(); if not busy { startEdit(str(c.id), str(c.title) if c.title else ""); } }}
                                            className="px-1 py-0"
                                        >REN</Button>
                                        <Button
                                            variant="ghost"
                                            onClick={lambda e: MouseEvent { e.stopPropagation(); if not busy { onDelete(str(c.id)); } }}
                                            className="px-1 py-0"
                                        >DEL</Button>
                                    </div>
                                    skip;
                                }}
                            </div>
                        }}
                    </div>
                </div>
            }}
        </div>
        {_mem_gauge({"used": residentGb, "total": ramGb})}
    </aside>;
}

